ed); color: #4c5c53; padding: 5px 8px; border-radius: 3px; font-size: 11px; font-weight: 700; }.seller { min-height: 42px; margin-top: auto; padding-top: 12px; border-top: 1px solid var(--border); display: flex; align-items: center; gap: 8px; color: var(--stone); font-size: 12px; }.avatar { display: grid; place-items: center; width: 26px; height: 26px; border-radius: 50%; background: #dfe7e1; color: var(--leaf); font-weight: 800; }.seller a { margin-left: auto; color: var(--ink); font-weight: 700; }.empty { padding: 70px 20px; text-align: center; border: 1px solid var(--border); background: white; }.empty h3 { margin: 0 0 8px; font-size: 22px; }.empty p { color: var(--stone); }.empty button { min-height: 44px; padding: 0 16px; border: 0; background: var(--leaf); color: white; border-radius: 4px; font-weight: 700; }.pagination { display: flex; justify-content: space-between; align-items: center; margin-top: 44px; padding-top: 20px; border-top: 1px solid var(--border); color: var(--stone); font-size: 13px; }.pagination div { display: flex; align-items: center; gap: 16px; }.pagination button { min-height: 44px; padding: 0 14px; border: 1px solid var(--border); background: white; border-radius: 4px; font-size: 12px; font-weight: 700; }.pagination button:disabled { opacity: .4; cursor: not-allowed; }
